-- Run as an administrator through the connected SQL tool. Every fixture rolls back.
begin;
select set_config('request.jwt.claim.sub',(select auth_user_id::text from workspace.system_users where auth_user_id is not null and status='active' and role in ('admin','super_admin') limit 1),true);
select set_config('maintenance.test_project',(select id::text from workspace.test_projects where not is_archived order by created_at limit 1),true);
select set_config('maintenance.second_actor_auth',(select auth_user_id::text from workspace.system_users where auth_user_id is not null and maintenance_private.account_access(id,true) and auth_user_id::text<>current_setting('request.jwt.claim.sub') limit 1),true);
select set_config('maintenance.archived_project',(select id::text from workspace.test_projects where is_archived limit 1),true);
set local role authenticated;
do $$
declare p uuid:=current_setting('maintenance.test_project')::uuid; i uuid:=gen_random_uuid(); n uuid:=gen_random_uuid(); legacy uuid:=gen_random_uuid(); r jsonb; original timestamptz; count_before integer; original_actor text:=current_setting('request.jwt.claim.sub');
begin
  r:=workspace.maintenance_workspace(p);
  count_before:=jsonb_array_length(r->'issues');
  r:=workspace.maintenance_create_fault(i,p,'QA-ROLLBACK-ONLY','無法開機');
  if r->>'maintenance_status'<>'pending' or r->>'system_id' is not null then raise exception 'unknown machine report failed'; end if;
  if (workspace.maintenance_create_fault(i,p,'QA-ROLLBACK-ONLY','無法開機'))->>'id'<>i::text then raise exception 'create retry duplicated'; end if;
  original:=(r->>'updated_at')::timestamptz;
  r:=workspace.maintenance_update_fault(i,original,'{"maintenance_status":"waiting_parts"}');
  begin perform workspace.maintenance_update_fault(i,original,'{"maintenance_status":"diagnosing"}'); raise exception 'stale write accepted'; exception when sqlstate 'PT409' then null; end;
  begin perform workspace.maintenance_update_fault(i,(r->>'updated_at')::timestamptz,'{"maintenance_status":"resolved"}'); raise exception 'uncategorized close accepted'; exception when sqlstate '22023' then null; end;
  begin perform workspace.maintenance_update_fault(i,(r->>'updated_at')::timestamptz,jsonb_build_object('assignee_user_ids',jsonb_build_array(gen_random_uuid()))); raise exception 'invalid owner accepted'; exception when sqlstate '22023' then null; end;
  r:=workspace.maintenance_update_fault(i,(r->>'updated_at')::timestamptz,jsonb_build_object('assignee_user_ids',jsonb_build_array(workspace.current_system_user_id()),'category','電源','maintenance_status','resolved'));
  if r->>'status'<>'resolved' then raise exception 'close did not map legacy status'; end if;
  r:=workspace.maintenance_update_fault(i,(r->>'updated_at')::timestamptz,'{"maintenance_status":"diagnosing"}');
  perform workspace.maintenance_add_note(i,n,'已換電源，交接待複測');
  perform workspace.maintenance_add_note(i,n,'已換電源，交接待複測');
  select to_jsonb(t) into r from workspace.issues t where id=i;
  r:=workspace.maintenance_update_fault(i,(r->>'updated_at')::timestamptz,jsonb_build_object('handover_message_id',n));
  r:=workspace.maintenance_update_fault(i,(r->>'updated_at')::timestamptz,'{"asset_identifier":"QA-RENAMED"}');
  if not exists(select 1 from workspace.maintenance_messages where issue_id=i and kind='edited' and metadata->>'previous_asset'='QA-ROLLBACK-ONLY' and metadata->>'asset'='QA-RENAMED') then raise exception 'machine edit history missing'; end if;
  if (workspace.maintenance_workspace(p)#>>'{issues,0,id}') is null then raise exception 'workspace is empty'; end if;
  if (select count(*) from workspace.maintenance_messages where id=n)<>1 then raise exception 'note retry duplicated'; end if;
  if jsonb_array_length(workspace.maintenance_thread(i)->'messages')<6 then raise exception 'audit events missing'; end if;
  if jsonb_array_length(workspace.maintenance_workspace(p)->'issues')<>count_before+1 then raise exception 'original issues disappeared'; end if;
  begin update workspace.maintenance_messages set body='tampered' where id=n; raise exception 'history mutable'; exception when insufficient_privilege then null; end;
  insert into workspace.issues(id,project_id,title,description,status,assigned_to,process_notes,solution) values(legacy,p,'原故障','<p>原描述</p>','closed','原工程師','<p>原處理</p>','原解決方式');
  select to_jsonb(t) into r from workspace.issues t where id=legacy;
  r:=workspace.maintenance_update_fault(legacy,(r->>'updated_at')::timestamptz,jsonb_build_object('assignee_user_ids',jsonb_build_array(workspace.current_system_user_id())));
  if r->>'status'<>'closed' or r->>'description'<>'<p>原描述</p>' or r->>'process_notes'<>'<p>原處理</p>' or r->>'solution'<>'原解決方式' then raise exception 'legacy content changed'; end if;
  if not exists(select 1 from workspace.maintenance_messages where issue_id=legacy and kind='assignees' and metadata->>'previous_assignees'='原工程師') then raise exception 'legacy owner history lost'; end if;
  perform set_config('request.jwt.claim.sub',current_setting('maintenance.second_actor_auth'),true);
  if jsonb_array_length(workspace.maintenance_thread(i)->'messages')<6 then raise exception 'second account cannot read updates'; end if;
  r:=workspace.maintenance_add_note(i,gen_random_uuid(),'另一帳號接手');
  if r->>'actor_id'<>workspace.current_system_user_id()::text then raise exception 'actor identity forged'; end if;
  perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
  begin perform workspace.maintenance_workspace(p); raise exception 'unknown identity can read'; exception when insufficient_privilege then null; end;
  perform set_config('request.jwt.claim.sub',original_actor,true);
  if (select sum(jsonb_array_length(workspace.maintenance_workspace(id)->'issues')) from workspace.test_projects)<>(select count(*) from workspace.issues) then raise exception 'project or archived issue missing'; end if;
  begin perform workspace.maintenance_create_fault(gen_random_uuid(),current_setting('maintenance.archived_project')::uuid,'QA-ARCHIVED','封存不得新增'); raise exception 'archived project writable'; exception when sqlstate '22023' then null; end;
  perform set_config('maintenance.test_result','create, idempotency, unknown asset, states, optimistic conflict, category guard, owner guard, note idempotency, handover, audit, original inclusion, immutable history, legacy preservation, cross-account handover, actor identity, denied unknown identity passed',true);
end $$;
select jsonb_build_object('result',current_setting('maintenance.test_result'),'all_fixtures','rolled back') as maintenance_contract;
rollback;
